<?php class DoctorPortalController extends Controller{function availability(){$this->auth(['doctor']);$db=Database::db();$q=$db->prepare('SELECT doctors.id FROM doctors WHERE user_id=?');$q->execute([$_SESSION['user']['id']]);$did=$q->fetchColumn();$h=$db->prepare('SELECT hospitals.id,hospitals.name FROM doctor_hospitals JOIN hospitals ON hospitals.id=doctor_hospitals.hospital_id WHERE doctor_hospitals.doctor_id=?');$h->execute([$did]);$a=$db->prepare('SELECT doctor_availability.*,hospitals.name hospital FROM doctor_availability LEFT JOIN hospitals ON hospitals.id=doctor_availability.hospital_id WHERE doctor_id=? ORDER BY COALESCE(available_date,"9999-12-31"),day_of_week,start_time');$a->execute([$did]);$this->view('doctor/availability',['hospitals'=>$h->fetchAll(PDO::FETCH_ASSOC),'availability'=>$a->fetchAll(PDO::FETCH_ASSOC)]);}function availabilityStore(){$this->auth(['doctor']);$db=Database::db();$q=$db->prepare('SELECT id FROM doctors WHERE user_id=?');$q->execute([$_SESSION['user']['id']]);$did=$q->fetchColumn();$db->prepare('INSERT INTO doctor_availability(doctor_id,hospital_id,available_date,day_of_week,start_time,end_time,status,slot_minutes) VALUES(?,?,?,?,?,?,?,?)')->execute([$did,$_POST['hospital_id']?:null,$_POST['available_date']?:null,$_POST['day_of_week']!==''?$_POST['day_of_week']:null,$_POST['start_time'],$_POST['end_time'],$_POST['status'],$_POST['slot_minutes']]);$this->go('/doctor/availability');}}